class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build(vals):
    head = None
    for v in reversed(vals):
        head = ListNode(v, head)
    return head


def dump(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out


def rotateRight(nums, k):
    head = build(nums)
    if head is None:
        return []
    n = 1
    tail = head
    while tail.next:
        tail = tail.next
        n += 1
    r = k % n
    if r == 0:
        return dump(head)
    tail.next = head
    new_tail = head
    for _ in range(n - r - 1):
        new_tail = new_tail.next
    new_head = new_tail.next
    new_tail.next = None
    return dump(new_head)
